def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for color in {v for row in grid for v in row if v != bg}:
        points = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dr in (-1, 1):
            for dc in (-1, 1):
                for r, c in points:
                    if (r + dr, c + dc) not in points:
                        continue
                    # Extend the diagonal segment from each endpoint, stopping at
                    # an existing non-background mark or the grid boundary.
                    for rr, cc, vr, vc in ((r - dr, c - dc, -dr, -dc),
                                           (r + 2*dr, c + 2*dc, dr, dc)):
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                            out[rr][cc] = color
                            rr += vr
                            cc += vc
    return out
